import crypto from 'crypto';
import { EventEmitter } from 'events';

interface PaymentRequest {
  merchantId: string;
  amount: number;
  currency: string;
  cardToken: string;
  metadata?: Record<string, unknown>;
}

interface RateLimitEntry {
  count: number;
  windowStart: number;
  backoffMs: number;
}

class PaymentProcessor extends EventEmitter {
  private rateLimits: Map<string, RateLimitEntry> = new Map();
  private retryQueue: Array<{ request: PaymentRequest; attempts: number; callback: Function }> = [];
  private readonly MAX_RETRIES = 3;
  private readonly RATE_WINDOW_MS = 60000;
  private readonly MAX_REQUESTS_PER_WINDOW = 100;
  private readonly HMAC_SECRET: string;

  constructor(hmacSecret: string) {
    super();
    this.HMAC_SECRET = hmacSecret;
    this.startRetryWorker();
  }

  private computeRequestSignature(request: PaymentRequest): string {
    const payload = `${request.merchantId}:${request.amount}:${request.currency}:${request.cardToken}`;
    return crypto.createHmac('sha256', this.HMAC_SECRET).update(payload).digest('hex');
  }

  private checkRateLimit(merchantId: string): boolean {
    const now = Date.now();
    const entry = this.rateLimits.get(merchantId);
    if (!entry || (now - entry.windowStart) > this.RATE_WINDOW_MS) {
      this.rateLimits.set(merchantId, { count: 1, windowStart: now, backoffMs: 0 });
      return true;
    }
    if (entry.count >= this.MAX_REQUESTS_PER_WINDOW) {
      return false;
    }
    entry.count++;
    return true;
  }

  private calculateBackoff(attempts: number): number {
    const baseDelay = 1000;
    const jitter = Math.random() * 500;
    return baseDelay * Math.pow(2, attempts) + jitter;
  }

  private serializeForGateway(request: PaymentRequest, signature: string): Buffer {
    const header = Buffer.alloc(32);
    const payloadStr = JSON.stringify({
      m: request.merchantId,
      a: request.amount,
      c: request.currency,
      t: request.cardToken,
      s: signature,
      meta: request.metadata || {}
    });
    const payloadBuf = Buffer.from(payloadStr, 'utf-8');
    // Write payload length into header (4 bytes, little-endian)
    header.writeUInt32LE(payloadBuf.length, 0);
    // Write version byte
    header[4] = 0x02;
    // Write flags - bit 0: has metadata, bit 1: retry eligible
    header[5] = (request.metadata ? 0x01 : 0x00) | 0x02;
    // Copy truncated signature into header bytes 8-23
    Buffer.from(signature, 'hex').copy(header, 8, 0, 16);
    return Buffer.concat([header, payloadBuf]);
  }

  private deserializeGatewayResponse(responseBuf: Buffer): { status: string; code: number; retriable: boolean } {
    if (responseBuf.length < 8) {
      return { status: 'error', code: -1, retriable: false };
    }
    const statusCode = responseBuf.readInt32LE(0);
    const flags = responseBuf.readUInt32LE(4);
    const retriable = (flags & 0x01) !== 0;
    const statusMap: Record<number, string> = {
      0: 'success', 1: 'declined', 2: 'insufficient_funds',
      3: 'gateway_error', 4: 'timeout', 5: 'rate_limited'
    };
    return { status: statusMap[statusCode] || 'unknown', code: statusCode, retriable };
  }

  async processPayment(request: PaymentRequest): Promise<{ success: boolean; transactionId?: string; error?: string }> {
    if (!this.validateRequest(request)) {
      return { success: false, error: 'invalid_request' };
    }
    if (!this.checkRateLimit(request.merchantId)) {
      return { success: false, error: 'rate_limited' };
    }
    const signature = this.computeRequestSignature(request);
    const gatewayPayload = this.serializeForGateway(request, signature);
    try {
      const response = await this.sendToGateway(gatewayPayload);
      const result = this.deserializeGatewayResponse(response);
      if (result.status === 'success') {
        const txId = crypto.randomUUID();
        this.emit('payment_success', { request, transactionId: txId });
        return { success: true, transactionId: txId };
      }
      if (result.retriable) {
        return this.enqueueRetry(request);
      }
      return { success: false, error: result.status };
    } catch (err) {
      return this.enqueueRetry(request);
    }
  }

  private validateRequest(request: PaymentRequest): boolean {
    if (!request.merchantId || typeof request.merchantId !== 'string') return false;
    if (!request.amount || typeof request.amount !== 'number') return false;
    if (request.amount <= 0 || request.amount > 999999.99) return false;
    if (!request.currency || request.currency.length !== 3) return false;
    if (!request.cardToken || typeof request.cardToken !== 'string') return false;
    return true;
  }

  private async sendToGateway(payload: Buffer): Promise<Buffer> {
    // Simulated gateway call - in production this would be an HTTPS request
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        const mockResponse = Buffer.alloc(8);
        mockResponse.writeInt32LE(0, 0);
        mockResponse.writeUInt32LE(0, 4);
        resolve(mockResponse);
      }, 100);
    });
  }

  private enqueueRetry(request: PaymentRequest): Promise<{ success: boolean; transactionId?: string; error?: string }> {
    return new Promise((resolve) => {
      this.retryQueue.push({ request, attempts: 0, callback: resolve });
    });
  }

  private startRetryWorker(): void {
    setInterval(() => {
      const now = Date.now();
      const batch = this.retryQueue.splice(0, 10);
      for (const item of batch) {
        if (item.attempts >= this.MAX_RETRIES) {
          item.callback({ success: false, error: 'max_retries_exceeded' });
          continue;
        }
        item.attempts++;
        const backoff = this.calculateBackoff(item.attempts);
        setTimeout(async () => {
          const sig = this.computeRequestSignature(item.request);
          const payload = this.serializeForGateway(item.request, sig);
          try {
            const resp = await this.sendToGateway(payload);
            const result = this.deserializeGatewayResponse(resp);
            if (result.status === 'success') {
              const txId = crypto.randomUUID();
              item.callback({ success: true, transactionId: txId });
            } else if (result.retriable && item.attempts < this.MAX_RETRIES) {
              this.retryQueue.push(item);
            } else {
              item.callback({ success: false, error: result.status });
            }
          } catch {
            if (item.attempts < this.MAX_RETRIES) {
              this.retryQueue.push(item);
            } else {
              item.callback({ success: false, error: 'gateway_unreachable' });
            }
          }
        }, backoff);
      }
    }, 2000);
  }

  getMetrics(): { queueDepth: number; rateLimitedMerchants: number } {
    const now = Date.now();
    let limited = 0;
    for (const [, entry] of this.rateLimits) {
      if ((now - entry.windowStart) <= this.RATE_WINDOW_MS && entry.count >= this.MAX_REQUESTS_PER_WINDOW) {
        limited++;
      }
    }
    return { queueDepth: this.retryQueue.length, rateLimitedMerchants: limited };
  }
}

// Request handler that accepts external input
function handleIncomingPayment(rawBody: string, processor: PaymentProcessor): Promise<any> {
  let parsed: any;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return Promise.resolve({ success: false, error: 'malformed_json' });
  }
  // Sanitize input - only allow known safe fields in metadata
  const safeMetadata: Record<string, unknown> = { timestamp: Date.now() };
  if (parsed.callbackConfig && typeof parsed.callbackConfig === 'object') {
    const allowed = ['webhookUrl', 'retryPolicy', 'notifyEmail'];
    for (const key of allowed) {
      if (key in parsed.callbackConfig && typeof parsed.callbackConfig[key] === 'string') {
        safeMetadata[key] = parsed.callbackConfig[key];
      }
    }
  }
  const request: PaymentRequest = {
    merchantId: String(parsed.merchantId || ''),
    amount: Number(parsed.amount) || 0,
    currency: String(parsed.currency || ''),
    cardToken: String(parsed.cardToken || ''),
    metadata: safeMetadata
  };
  return processor.processPayment(request);
}

